#!/bin/bash
set -euo pipefail
WEB=/var/www/fusionpbx/app/agent_dashboard

B64_skykin_config_php=''
echo "${B64_skykin_config_php}" | base64 -d > /tmp/skykin_config.php
docker cp /tmp/skykin_config.php skykin-web:$WEB/skykin_config.php
echo deployed skykin_config.php

B64_data_php=''
echo "${B64_data_php}" | base64 -d > /tmp/data.php
docker cp /tmp/data.php skykin-web:$WEB/data.php
echo deployed data.php

B64_index_php=''
echo "${B64_index_php}" | base64 -d > /tmp/index.php
docker cp /tmp/index.php skykin-web:$WEB/index.php
echo deployed index.php

B64_supervisor_php=''
echo "${B64_supervisor_php}" | base64 -d > /tmp/supervisor.php
docker cp /tmp/supervisor.php skykin-web:$WEB/supervisor.php
echo deployed supervisor.php

docker exec skykin-web php -r 'opcache_reset();' 2>/dev/null || true
docker exec skykin-web php -r '
require "/var/www/fusionpbx/app/agent_dashboard/skykin_config.php";
$ivr=["direction"=>"inbound","billsec"=>20,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"+251116198037","caller_id_number"=>"+251911111111"];
$agent=["direction"=>"inbound","billsec"=>40,"hangup_cause"=>"NORMAL_CLEARING","destination_number"=>"202","last_arg"=>"user/202@ahununu","cc_agent_bridged"=>"/202@ahununu","caller_id_number"=>"+251911111111"];
echo "ivr=", skykin_cdr_result_label($ivr), "\n";
echo "agent=", skykin_cdr_result_label($agent), "\n";
$legs=[];
for ($i=5;$i<=8;$i++) {
  $legs[]=["direction"=>"inbound","billsec"=>0,"duration"=>1,"hangup_cause"=>"CALL_REJECTED","destination_number"=>"+25111619803$i","caller_id_number"=>"+251911000111","start_epoch"=>1700000000+$i];
}
$c=skykin_cdr_collapse_hunt_legs($legs);
echo "blacklist_hunt_count=", count($c), " label=", skykin_cdr_result_label($c[0]), "\n";
'
echo DONE
